import { createLedger, transfer, getBalance, resetSnapshotCache } from './src/index.js'

// --- Invariant 3: getBalance must equal fold of the current stream ---
{
  resetSnapshotCache()
  const ledger = createLedger()
  ledger.append({ type: 'credit', account: 'alice', amountCents: 10000, ts: 1, id: 'f1' })
  ledger.append({ type: 'credit', account: 'bob', amountCents: 5000, ts: 2, id: 'f2' })
  getBalance(ledger, 'alice') // prime cache at count 2
  transfer(ledger, 'alice', 'bob', 3000, {}) // count now 4
  const folded = ledger.fold()
  console.log('inv3 getBalance(alice) =', getBalance(ledger, 'alice'), ' fold =', folded.alice,
    getBalance(ledger, 'alice') === folded.alice ? 'OK' : 'VIOLATION')
}

// --- Invariant 2: no overdraft ---
{
  resetSnapshotCache()
  const ledger = createLedger()
  ledger.append({ type: 'credit', account: 'alice', amountCents: 10000, ts: 1, id: 'f1' })
  ledger.append({ type: 'credit', account: 'bob', amountCents: 5000, ts: 2, id: 'f2' })
  getBalance(ledger, 'alice') // prime cache at count 2
  transfer(ledger, 'alice', 'bob', 8000, {}) // count 4; alice really has 2000
  try {
    transfer(ledger, 'alice', 'bob', 8000, {}) // stale cache says alice has 10000 -> passes
    console.log('inv2 alice balance after two 8000 transfers =', ledger.fold().alice, '-> NEGATIVE: VIOLATION')
  } catch (e) {
    console.log('inv2 second transfer threw:', e.message, '-> OK')
  }
}

// --- Cross-ledger cache pollution ---
{
  resetSnapshotCache()
  const a = createLedger()
  a.append({ type: 'credit', account: 'alice', amountCents: 10000, ts: 1, id: 'a1' })
  a.append({ type: 'credit', account: 'bob', amountCents: 5000, ts: 2, id: 'a2' })
  const b = createLedger()
  b.append({ type: 'credit', account: 'carol', amountCents: 777, ts: 1, id: 'b1' })
  b.append({ type: 'credit', account: 'dave', amountCents: 888, ts: 2, id: 'b2' })
  getBalance(a, 'alice') // caches ledger a's fold globally
  console.log('pollution getBalance(b, carol) =', getBalance(b, 'carol'), '(expected 777)',
    getBalance(b, 'carol') === 777 ? 'OK' : 'VIOLATION')
}

/**
 * Balance snapshot cache. Folding the whole stream on every read is expensive,
 * so each ledger keeps a cached fold result; on a read, only the events
 * appended since the last refresh are applied. The cached balances therefore
 * always equal a direct fold of the current event stream (invariant:
 * getBalance == fold), while still avoiding a full replay on every read.
 */
const caches = new WeakMap()

export function getBalance(ledger, account) {
  let cache = caches.get(ledger)
  if (cache === undefined) {
    cache = { atCount: 0, balances: {} }
    caches.set(ledger, cache)
  }
  const events = ledger.events()
  if (cache.atCount !== events.length) {
    for (const event of events.slice(cache.atCount)) {
      const current = cache.balances[event.account] ?? 0
      cache.balances[event.account] =
        current + (event.type === 'credit' ? event.amountCents : -event.amountCents)
    }
    cache.atCount = events.length
  }
  return cache.balances[account] ?? 0
}

export function resetSnapshotCache() {
  caches = new WeakMap()
}

import { createLedger, transfer, getBalance, resetSnapshotCache, createRebateHook } from './src/index.js'

function seed() {
  resetSnapshotCache()
  const ledger = createLedger()
  ledger.append({ type: 'credit', account: 'a', amountCents: 10000, ts: 1, id: 'a' })
  ledger.append({ type: 'credit', account: 'b', amountCents: 7000, ts: 2, id: 'b' })
  ledger.append({ type: 'credit', account: 'c', amountCents: 3000, ts: 3, id: 'c' })
  return ledger
}

let rng = 12345
const rand = (n) => { rng = (rng * 1103515245 + 12345) & 0x7fffffff; return rng % n }

const accounts = ['a', 'b', 'c', 'd']
let totalOps = 0

for (let iter = 0; iter < 300; iter++) {
  const ledger = seed()
  const hook = createRebateHook(ledger, [0, 5, 10, 25, 50][rand(5)])
  let initial = Object.values(ledger.fold()).reduce((s, v) => s + v, 0)
  for (let op = 0; op < 60; op++) {
    const from = accounts[rand(accounts.length)]
    const to = accounts[rand(accounts.length)]
    const amount = 1 + rand(9000)
    const useHook = rand(3) === 0
    try {
      transfer(ledger, from, to, amount, useHook ? { onSettled: hook } : {})
      totalOps++
    } catch (e) {
      // insufficient funds / amount errors are fine
    }
    // invariant 3: every read matches fold
    for (const acct of accounts) {
      const g = getBalance(ledger, acct)
      const f = ledger.fold()[acct] ?? 0
      if (g !== f) { console.error('INV3 FAIL', { iter, op, acct, g, f }); process.exit(1) }
    }
    // invariant 2: no negative balances
    for (const acct of accounts) {
      const b = ledger.fold()[acct] ?? 0
      if (b < 0) { console.error('INV2 FAIL (overdraft)', { iter, op, acct, b }); process.exit(1) }
    }
    // invariant 1: conservation
    const now = Object.values(ledger.fold()).reduce((s, v) => s + v, 0)
    if (now !== initial) { console.error('INV1 FAIL (conservation)', { iter, op, initial, now }); process.exit(1) }
  }
}

// interleaved multi-ledger reads
resetSnapshotCache()
const l1 = createLedger()
l1.append({ type: 'credit', account: 'x', amountCents: 5000, ts: 1, id: 'x' })
const l2 = createLedger()
l2.append({ type: 'credit', account: 'y', amountCents: 9000, ts: 1, id: 'y' })
l2.append({ type: 'credit', account: 'z', amountCents: 1000, ts: 2, id: 'z' })
getBalance(l1, 'x') // prime l1
transfer(l1, 'x', 'y', 2000, {}) // l1 events: 2
getBalance(l2, 'z') // must be 1000, not l1's fold
if (getBalance(l2, 'z') !== 1000 || getBalance(l1, 'x') !== 3000) {
  console.error('CROSS-LEDGER FAIL'); process.exit(1)
}

console.log('fuzz OK —', totalOps, 'successful transfers, all invariants hold')
